const $=id=>document.getElementById(id);
const GameAI={mode:'mock',analyze({description,points}){return /꽃|flower/.test(description)?{name:'꽃잎 지팡이',icon:'🌸',kind:'flower',attack:19,skill:'만개 · 26 피해 + 체력 14 회복',reason:'꽃 설명 → 회복형 무기'}:/시계|시간|clock/.test(description)?{name:'시간의 고리',icon:'🕐',kind:'clock',attack:21,skill:'시간 정지 · 28 피해 + 반격 취소',reason:'시계 설명 → 제어형 무기'}:{name:'낙서 블레이드',icon:'⚔️',kind:'sword',attack:Math.min(28,18+Math.floor(points/35)),skill:'잉크 폭발 · 기본 공격의 2배 피해',reason:'그림의 선 좌표 수 → 공격력 (최대 28)'}}};
let canvas=$('canvas'),ctx=canvas.getContext('2d'),drawing=false,points=0,weapon=null,hp=100,enemy=110,bt=0,uses=2;ctx.lineWidth=5;ctx.lineCap='round';ctx.strokeStyle=GamePalette.tokens.muted;function xy(e){let r=canvas.getBoundingClientRect();return[(e.clientX-r.left)*canvas.width/r.width,(e.clientY-r.top)*canvas.height/r.height]}canvas.onpointerdown=e=>{e.preventDefault();drawing=true;canvas.setPointerCapture(e.pointerId);let [x,y]=xy(e);ctx.beginPath();ctx.moveTo(x,y);ctx.lineTo(x+.1,y+.1);ctx.stroke();points++};canvas.onpointermove=e=>{if(!drawing)return;let [x,y]=xy(e);ctx.lineTo(x,y);ctx.stroke();points++};canvas.onpointerup=canvas.onpointercancel=()=>drawing=false;
function clearDrawing(){ctx.clearRect(0,0,700,360);points=0;$('drawDesc').value=''}function example(type){clearDrawing();ctx.beginPath();if(type==='flower'){ctx.moveTo(350,190);ctx.lineTo(350,320);ctx.stroke();for(let i=0;i<6;i++){let a=i*Math.PI/3;ctx.beginPath();ctx.ellipse(350+Math.cos(a)*50,145+Math.sin(a)*50,35,25,a,0,Math.PI*2);ctx.stroke()}ctx.beginPath();ctx.arc(350,145,26,0,Math.PI*2);ctx.stroke();$('drawDesc').value='꽃'}else{ctx.arc(350,175,115,0,Math.PI*2);ctx.moveTo(350,90);ctx.lineTo(350,175);ctx.lineTo(420,195);ctx.stroke();$('drawDesc').value='시계'}points=100}
async function analyze(){if(!points&&!$('drawDesc').value.trim()){$('weapon').textContent='그림을 그리거나 설명을 입력해 주세요.';return}weapon=await GameAI.analyze({description:$('drawDesc').value,points});$('weapon').textContent=`${weapon.icon} ${weapon.name}\n공격력 ${weapon.attack} · ${weapon.skill}\n${GameAI.mode==='live'?'API 설명 분석':'모의 분석'}: ${weapon.reason}`;$('weaponIcon').textContent=weapon.icon;resetFight()}
function updateFight(){$('myHp').textContent=hp+'/100';$('enemyHp').textContent=enemy+'/110';$('myBar').style.width=hp+'%';$('enemyBar').style.width=enemy/110*100+'%';['attack','skill','guard'].forEach(x=>$(x).disabled=!weapon||hp<=0||enemy<=0);$('skill').disabled=!weapon||hp<=0||enemy<=0||uses<=0;$('skill').textContent=`특수 기술 (${uses}/2)`}function log(t){let p=document.createElement('div');p.textContent=t;$('battleLog').prepend(p)}function resetFight(){hp=100;enemy=110;bt=0;uses=2;$('battleLog').textContent=weapon?'무기 준비 완료! 상대의 다음 행동: 공격 (14 피해)':'먼저 무기를 만들어 주세요.';updateFight()}
function fight(action){if(!weapon||hp<=0||enemy<=0||action==='skill'&&uses<=0)return;let dmg=action==='guard'?0:weapon.attack,skip=false;if(action==='skill'){uses--;dmg=weapon.kind==='flower'?26:weapon.kind==='clock'?28:weapon.attack*2;if(weapon.kind==='flower')hp=Math.min(100,hp+14);if(weapon.kind==='clock')skip=true}enemy=Math.max(0,enemy-dmg);let incoming=[14,25,0][bt%3];if(action==='guard')incoming=Math.ceil(incoming*.25);if(skip||enemy===0)incoming=0;hp=Math.max(0,hp-incoming);bt++;log(`${bt}턴 · ${action==='guard'?'방어':action==='skill'?weapon.skill.split(' · ')[0]:'기본 공격'} → ${dmg} 피해 / ${skip?'시간 정지! ':''}받은 피해 ${incoming}`);if(enemy===0||hp===0)log(enemy===0?'🏆 승리! 당신의 낙서가 수호자를 이겼어요.':'다시 도전! 방어로 강공격을 버텨보세요.');else log(`다음 상대 행동: ${['공격 (14 피해)','강공격 (25 피해)','휴식 (0 피해)'][bt%3]}`);updateFight()}

const mockAnalyze=GameAI.analyze;let busy=false;
function changeAI(mode){if(busy)return;GameAI.mode=mode;GameAI.analyze=mode==='mock'?mockAnalyze:async(input)=>{if(location.protocol==='file:')throw Error('Gemini는 서버로 실행해 주세요. README를 확인하세요.');if(!input.description.trim())throw Error('Gemini 모드에서는 그림 설명을 입력해 주세요.');const r=await fetch('/api/ai/analyze',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(input),signal:AbortSignal.timeout(65000)});const b=await r.json();if(!r.ok)throw Error(b.error||'API 오류');return b.data};$('aiBadge').textContent=mode==='live'?'Gemini · 호출 전':'모의 AI';$('apiError').textContent='';weapon=null;$('weaponIcon').textContent='✏️';$('weapon').textContent='새 무기를 만들어 주세요.';resetFight()}
const originalAnalyze=analyze;analyze=async()=>{if(busy)return;busy=true;const controls=[...document.querySelectorAll('button,input,select')];const disabled=controls.map(c=>c.disabled);controls.forEach(c=>c.disabled=true);$('apiError').textContent='';$('apiStatus').textContent='무기 생성 중 · 혼잡 시 자동 재시도';try{await originalAnalyze();if(weapon)$('aiBadge').textContent=GameAI.mode==='live'?'Gemini 응답 수신 완료':'모의 AI'}catch(e){$('apiError').textContent=e.name==='TimeoutError'?'응답 시간 초과. 다시 시도해 주세요.':e.message}finally{busy=false;controls.forEach((c,i)=>c.disabled=disabled[i]);updateFight();$('apiStatus').textContent=GameAI.mode==='live'?'그림 설명을 Gemini로 분석':'모의 AI · 외부 전송 없음'}};
resetFight();if(location.protocol!=='file:')fetch('/api/status').then(r=>r.json()).then(s=>$('apiStatus').textContent=s.configured?'Gemini 설정됨 · 모드 선택 후 사용':'Gemini 키 미설정 · 모의 모드 사용 가능').catch(()=>{});
